// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
  JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const entrada = $input.all();

// Obtém os clientes e investimentos do JSON recebido
const dados = entrada[0].json;

const clientes = dados.body?.clientes ?? dados.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// Mensagens fixas para cada perfil
const mensagensPerfil = {
  "Conservador": "Olá, {nome}! Considerando seu perfil CONSERVADOR, vamos priorizar investimentos que tendem a oferecer maior previsibilidade e menor exposição a oscilações. Confira as opções disponíveis para você.",

  "Moderado": "Olá, {nome}! Considerando seu perfil MODERADO, vamos apresentar opções que buscam equilibrar segurança e potencial de retorno, incluindo alternativas com diferentes níveis de risco e prazos.",

  "Arrojado": "Olá, {nome}! Considerando seu perfil ARROJADO, vamos apresentar opções com maior potencial de valorização, mas que também podem apresentar oscilações significativas e perdas. Confira as alternativas disponíveis."
};

// Converte "R$ 12.500,00" para 12500
function converterSaldo(valor) {
  if (typeof valor === "number") return valor;

  return Number(
    String(valor ?? "")
      .replace(/[R$\s]/g, "")
      .replace(/\./g, "")
      .replace(",", ".")
  ) || 0;
}

// Converte o investimento mínimo para número
function converterMinimo(valor) {
  if (typeof valor === "number") return valor;

  return Number(
    String(valor ?? "")
      .replace(/[R$\s]/g, "")
      .replace(/\./g, "")
      .replace(",", ".")
  ) || 0;
}

// Formata valores em reais
function formatarReal(valor) {
  return valor.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// Explica a rentabilidade conforme o tipo informado
function explicarRentabilidade(rentabilidade) {
  const valor = String(rentabilidade ?? "").trim();

  if (/^variável$/i.test(valor)) {
    return "Rentabilidade variável: não há taxa de retorno fixa ou garantida. O resultado depende do desempenho do investimento e pode haver perdas.";
  }

  if (/^IPCA\s*\+/i.test(valor)) {
    return `Rentabilidade indicada como ${valor}. Isso representa uma parcela de retorno acima da inflação medida pelo IPCA, conforme as condições do produto. O resultado depende das regras, do prazo e das condições contratadas.`;
  }

  if (/^\d+(?:[.,]\d+)?%$/.test(valor)) {
    return `Rentabilidade informada: ${valor}. A periodicidade dessa taxa (mensal, anual ou outra) precisa ser confirmada nas condições do produto; ela não deve ser presumida apenas pelo percentual.`;
  }

  return `Rentabilidade informada: ${valor}. Consulte as condições do produto para entender como ela é calculada.`;
}

// Gera uma mensagem personalizada para cada cliente
const resultados = clientes.map(cliente => {
  const nome = cliente.nome ?? "Cliente";
  const perfil = cliente.perfil ?? "";
  const saldo = converterSaldo(cliente.saldo);

  const mensagemBase = mensagensPerfil[perfil]
    ? mensagensPerfil[perfil].replace("{nome}", nome)
    : `Olá, ${nome}! Vamos verificar os investimentos disponíveis para o seu perfil (${perfil || "não informado"}).`;

  // Filtra investimentos compatíveis com o perfil
  const produtosPerfil = investimentos.filter(
    investimento => investimento.perfil === perfil
  );

  const produtosElegiveis = produtosPerfil.filter(
    investimento => saldo >= converterMinimo(investimento.minimo)
  );

  let mensagem = `${mensagemBase}\n\n`;
  mensagem += `Seu saldo informado é de ${formatarReal(saldo)}.\n\n`;

  if (produtosPerfil.length === 0) {
    mensagem += "Não encontramos produtos cadastrados para o seu perfil no momento.";
  } else {
    mensagem += "INVESTIMENTOS DO SEU PERFIL:\n\n";

    for (const investimento of produtosPerfil) {
      const minimo = converterMinimo(investimento.minimo);
      const elegivel = saldo >= minimo;

      mensagem += `Produto: ${investimento.produto}\n`;
      mensagem += `Investimento mínimo: ${formatarReal(minimo)}\n`;
      mensagem += `Rentabilidade: ${investimento.rentabilidade}\n`;
      mensagem += `${explicarRentabilidade(investimento.rentabilidade)}\n`;

      if (elegivel) {
        mensagem += "Situação: seu saldo informado atende ao valor mínimo anunciado.\n";
      } else {
        mensagem += `Situação: faltam ${formatarReal(minimo - saldo)} para atingir o mínimo anunciado.\n`;
      }

      mensagem += "\n";
    }

    mensagem += "RESUMO:\n";

    if (produtosElegiveis.length > 0) {
      mensagem += "Seu saldo atende ao investimento mínimo dos seguintes produtos: ";
      mensagem += produtosElegiveis
        .map(produto => produto.produto)
        .join(", ");
      mensagem += ".\n";
    } else {
      mensagem += "Seu saldo não atinge o mínimo anunciado de nenhum produto cadastrado para o seu perfil.\n";
    }
  }

  mensagem += "\nImportante: os valores mínimos e as rentabilidades devem ser confirmados nas condições vigentes de cada produto. Rentabilidade passada ou indicada não garante resultados futuros. Considere também impostos, taxas, liquidez, prazo e possibilidade de perdas antes de investir.";

  return {
    json: {
      nome,
      email: cliente.email ?? "",
      perfil,
      saldo,
      mensagem,
      investimentosDoPerfil: produtosPerfil.map(investimento => ({
        produto: investimento.produto,
        minimo: converterMinimo(investimento.minimo),
        rentabilidade: investimento.rentabilidade,
        saldoAtendeMinimo: saldo >= converterMinimo(investimento.minimo)
      }))
    }
  };
});

return resultados;

