const items = $input.all();

return items.map(item => {
  const entrada = item.json;

  // Procura o texto em estruturas comuns de saída
  let conteudo =
    entrada.content?.[0]?.text ??
    entrada.output?.[0]?.content?.[0]?.text ??
    entrada.output?.[0]?.text ??
    entrada.text ??
    entrada.message?.content?.[0]?.text ??
    entrada.message?.content ??
    entrada;

  // Se o conteúdo for uma string, tenta extrair o JSON
  let dados = conteudo;

  if (typeof conteudo === "string") {
    let texto = conteudo.trim();

    texto = texto
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();

    const inicio = texto.indexOf("{");
    const fim = texto.lastIndexOf("}");

    if (inicio === -1 || fim < inicio) {
      throw new Error(
        "JSON não encontrado. Campos recebidos: " +
        Object.keys(entrada).join(", ")
      );
    }

    dados = JSON.parse(texto.slice(inicio, fim + 1));
  }

  // Se a estrutura encontrada ainda for um array de conteúdo
  if (Array.isArray(dados)) {
    const bloco = dados.find(x => x?.text != null);
    if (bloco) {
      dados = typeof bloco.text === "string"
        ? JSON.parse(bloco.text)
        : bloco.text;
    }
  }

  if (!dados || typeof dados !== "object") {
    throw new Error("A resposta não contém um objeto JSON válido.");
  }

  return {
    json: {
      Subject: String(
        dados.Subject ?? dados["Subject:"] ?? ""
      ).trim(),

      Text_body: String(
        dados.Text_Body ??
        dados.Text_body ??
        dados["Text_Body:"] ??
        ""
      ).trim(),

      html_body: String(
        dados.HTML_Body ??
        dados.html_body ??
        dados["HTML_Body:"] ??
        ""
      ).replace(/\\([<>])/g, "$1").trim()
    }
  };
});
